  const canvasRef = useRef();
  const [imagePaths, setImagePaths] = useState([]);
  const [isFading, setIsFading] = useState(false);
  const [effects, setEffects] = useState({
    grain: { intensity: 5, gamma: 1.2 },
    scanlines: { gap: 4, alpha: 0.05 },
    glitch: { lineHeight: 2, shiftAmount: 0 },
    saturation: { value: 100 }
  });
  const animationRef = useRef();
  const navigate = useNavigate();

  useEffect(() => {
    const stored = JSON.parse(localStorage.getItem("selectedImages") || "[]");
    if (!stored.length) {
      navigate("/");
      return;
    }
    setImagePaths(stored);
    generateImage(stored);
    return () => cancelAnimationFrame(animationRef.current);
  }, []);

  // --- [이펙트 및 유틸리티 함수] ---
  const generateGrain = (ctx, width, height) => {
    const { intensity } = effects.grain;
    if (intensity <= 0) return;
    const grainData = ctx.getImageData(0, 0, width, height);
    const data = grainData.data;
    for (let i = 0; i < data.length; i += 4) {
      const noise = Math.floor(Math.random() * intensity) - intensity / 2;
      data[i] = Math.min(255, Math.max(0, data[i] + noise));
      data[i + 1] = Math.min(255, Math.max(0, data[i + 1] + noise));
      data[i + 2] = Math.min(255, Math.max(0, data[i + 2] + noise));
    }
    ctx.putImageData(grainData, 0, 0);
  };

  const applyScanlines = (ctx, width, height) => {
    // 스캔라인은 전체 분위기를 위해 마지막 레이어에만 적용하거나 전체에 약하게 적용
    const { alpha } = effects.scanlines;
    if (alpha <= 0) return;
    ctx.save();
    ctx.fillStyle = `rgba(0,0,0,${alpha})`;
    for (let y = 0; y < height; y += effects.scanlines.gap) {
      ctx.fillRect(0, y, width, 1);
    }
    ctx.restore();
  };

  const applyGlitchEffect = (ctx, width, height) => {
    const { shiftAmount } = effects.glitch;
    if (shiftAmount <= 0) return;
    for (let y = 0; y < height; y += effects.glitch.lineHeight * 4) {
      const shift = (Math.random() - 0.5) * shiftAmount;
      const imageData = ctx.getImageData(0, y, width, effects.glitch.lineHeight);
      ctx.putImageData(imageData, shift, y);
    }
  };

  const applySaturation = (ctx, width, height) => {
    const { value } = effects.saturation;
    if (value === 100) return;
    const imageData = ctx.getImageData(0, 0, width, height);
    const data = imageData.data;
    for (let i = 0; i < data.length; i += 4) {
      const r = data[i];
      const g = data[i + 1];
      const b = data[i + 2];
      const gray = Math.round(0.299 * r + 0.587 * g + 0.114 * b);
      const sat = value / 100;
      data[i] = Math.round(gray + (r - gray) * sat);
      data[i + 1] = Math.round(gray + (g - gray) * sat);
      data[i + 2] = Math.round(gray + (b - gray) * sat);
    }
    ctx.putImageData(imageData, 0, 0);
  };

  const handleArchive = () => {
    const canvas = canvasRef.current;
    const compressedImageData = compressImage(canvas);
    const timestamp = new Date().toISOString();
    const archives = JSON.parse(localStorage.getItem("archivedImages") || "[]");
    archives.push({ imageData: compressedImageData, timestamp, effects: { ...effects } });
    const trimmedArchives = archives.slice(-10);
    localStorage.setItem("archivedImages", JSON.stringify(trimmedArchives));
    alert("Image archived successfully!");
  };

  const compressImage = (canvas) => {
    const tempCanvas = document.createElement('canvas');
    const tempCtx = tempCanvas.getContext('2d');
    tempCanvas.width = 1080;
    tempCanvas.height = 1080;
    tempCtx.drawImage(canvas, 0, 0, 1080, 1080);
    return tempCanvas.toDataURL('image/png');
  };

  // --- [핵심 로직: 프로세스 레이어 드로잉] ---
  const drawProcessLayers = (ctx, width, height, sourceCanvas) => {
    const sourceCtx = sourceCanvas.getContext('2d');

    // 1. 공통 데이터 계산 (방사형 네트워크 로직)
    // 전체 데이터를 미리 계산해두고, 각 레이어에서 다르게 렌더링합니다.
    const tileSize = 15; 
    const cols = Math.ceil(width / tileSize);
    const rows = Math.ceil(height / tileSize);

    const nodes = [];
    const centerX = width / 2;
    const centerY = height / 2; // 각 스트립의 높이가 아니라, 전체 캔버스 기준 계산 후 오프셋 적용

    // 스트립 높이 (4등분)
    const stripH = height / 4;
    // 시각적 표현을 위해 데이터 생성 시 사용할 반지름 (스트립 높이에 맞춤)
    const maxRadius = (stripH * 0.8) / 2; 

    // 데이터 분석
    for (let y = 0; y < rows; y++) {
      for (let x = 0; x < cols; x++) {
        const tileData = sourceCtx.getImageData(x * tileSize, y * tileSize, tileSize, tileSize);
        const data = tileData.data;
        let r=0, g=0, b=0, count=0;
        for(let i=0; i<data.length; i+=4) {
            if(data[i+3] > 0) { r+=data[i]; g+=data[i+1]; b+=data[i+2]; count++; }
        }

        if (count > 0) {
            r = Math.floor(r/count); g = Math.floor(g/count); b = Math.floor(b/count);

            // Hue & Brightness 계산
            let hue = 0;
            const max = Math.max(r, g, b);
            const min = Math.min(r, g, b);
            if (max === min) hue = 0;
            else if (max === r) hue = (g - b) / (max - min);
            else if (max === g) hue = 2 + (b - r) / (max - min);
            else hue = 4 + (r - g) / (max - min);
            hue *= 60; if (hue < 0) hue += 360;

            const brightness = (r+g+b)/3;
            const saturation = max === 0 ? 0 : (max - min) / max;

            // 방사형 좌표 계산 (0,0 기준)
            const angle = (hue * Math.PI / 180);
            const distance = (brightness / 255) * maxRadius * (0.5 + Math.random() * 0.5);

            // 상대 좌표 (중심점 기준)
            const relX = Math.cos(angle) * distance;
            const relY = Math.sin(angle) * distance;

            nodes.push({
                relX, relY, // 상대 좌표 저장
                r, g, b,
                color: `rgb(${r},${g},${b})`,
                size: tileSize * (0.2 + saturation * 0.8),
                hue
            });
        }
      }
    }

    // --- [드로잉 함수] ---
    // 각 레이어의 Y 시작점
    const y1 = 0;
    const y2 = stripH;
    const y3 = stripH * 2;
    const y4 = stripH * 3;

    // 1. Layer 1: Source (원본 합성 이미지)
    // 원본을 찌그러트리지 않고, 가운데 부분을 크롭해서 보여줌
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, y1, width, stripH);
    ctx.clip();
    // 비율 유지하며 꽉 차게 그리기 (Cover)
    const scale = Math.max(width / sourceCanvas.width, stripH / sourceCanvas.height);
    const drawW = sourceCanvas.width * scale;
    const drawH = sourceCanvas.height * scale;
    ctx.drawImage(sourceCanvas, (width - drawW)/2, y1 + (stripH - drawH)/2, drawW, drawH);
    // 어두운 오버레이 (텍스트 가독성)
    ctx.fillStyle = "rgba(0,0,0,0.3)";
    ctx.fillRect(0, y1, width, stripH);
    ctx.restore();

    // 2. Layer 2: Extraction (점/노드만)
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, y2, width, stripH);
    ctx.clip();
    ctx.fillStyle = "#111"; // 배경
    ctx.fillRect(0, y2, width, stripH);

    // 점 그리기
    nodes.forEach(node => {
        const cx = width / 2;
        const cy = y2 + stripH / 2; // 해당 스트립의 중앙

        ctx.fillStyle = node.color;
        ctx.beginPath();
        ctx.arc(cx + node.relX, cy + node.relY, node.size * 0.8, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.restore();

    // 3. Layer 3: Structure (선/네트워크만)
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, y3, width, stripH);
    ctx.clip();
    ctx.fillStyle = "#0a0a0a"; // 더 어두운 배경
    ctx.fillRect(0, y3, width, stripH);

    // 선 그리기
    const cx3 = width / 2;
    const cy3 = y3 + stripH / 2;
    ctx.lineWidth = 0.5;

    // 연결 로직 (일부만 연결)
    for(let i=0; i<nodes.length; i+=2) { // 성능 위해 건너뛰며 연결
        if (Math.random() > 0.1) continue;
        const node = nodes[i];

        // 인접한 노드 찾기 (배열 인덱스 기준 단순화)
        for(let j=1; j<5; j++) {
            const neighbor = nodes[(i+j) % nodes.length];
            if (Math.abs(node.hue - neighbor.hue) < 40) { // 비슷한 색끼리
                ctx.strokeStyle = "rgba(255, 255, 255, 0.3)"; // 흰색 선
                ctx.beginPath();
                ctx.moveTo(cx3 + node.relX, cy3 + node.relY);
                ctx.lineTo(cx3 + neighbor.relX, cy3 + neighbor.relY);
                ctx.stroke();
            }
        }
    }
    ctx.restore();


    // 4. Layer 4: Synthesis (최종 합성)
    ctx.save();
    ctx.beginPath();
    ctx.rect(0, y4, width, stripH);
    ctx.clip();
    ctx.fillStyle = "#000";
    ctx.fillRect(0, y4, width, stripH);

    const cx4 = width / 2;
    const cy4 = y4 + stripH / 2;

    // 선 + 점 + 글로우 효과
    ctx.globalCompositeOperation = 'screen'; // 빛나는 효과

    // 선 먼저
    for(let i=0; i<nodes.length; i+=2) {
        if (Math.random() > 0.1) continue;
        const node = nodes[i];
        for(let j=1; j<5; j++) {
            const neighbor = nodes[(i+j) % nodes.length];
            if (Math.abs(node.hue - neighbor.hue) < 40) {
                ctx.strokeStyle = `rgba(${node.r},${node.g},${node.b}, 0.2)`; // 색상 선
                ctx.beginPath();
                ctx.moveTo(cx4 + node.relX, cy4 + node.relY);
                ctx.lineTo(cx4 + neighbor.relX, cy4 + neighbor.relY);
                ctx.stroke();
            }
        }
    }

    // 점 그리기
    nodes.forEach(node => {
        ctx.fillStyle = node.color;
        ctx.beginPath();
        ctx.arc(cx4 + node.relX, cy4 + node.relY, node.size, 0, Math.PI * 2);
        ctx.fill();
    });
    ctx.restore();


    // --- [라벨링 및 데코레이션] ---
    // 구분선
    ctx.strokeStyle = "#fff";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(0, y2); ctx.lineTo(width, y2);
    ctx.moveTo(0, y3); ctx.lineTo(width, y3);
    ctx.moveTo(0, y4); ctx.lineTo(width, y4);
    ctx.stroke();

    // 텍스트 라벨
    ctx.font = "bold 24px Courier New, monospace";
    ctx.fillStyle = "#fff";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";

    const pad = 20;
    ctx.fillText("01. SOURCE DATA", pad, y1 + pad);
    ctx.fillText("02. NODE EXTRACTION", pad, y2 + pad);
    ctx.fillText("03. TOPOLOGY STRUCTURE", pad, y3 + pad);
    ctx.fillText("04. FINAL SYNTHESIS", pad, y4 + pad);

    // 상세 정보 (작게)
    ctx.font = "14px Courier New, monospace";
    ctx.fillStyle = "rgba(255,255,255,0.6)";
    ctx.fillText(`INPUT: MERGED COMPOSITE`, pad, y1 + pad + 30);
    ctx.fillText(`POINTS: ${nodes.length}`, pad, y2 + pad + 30);
    ctx.fillText(`ALGORITHM: RADIAL MAPPING`, pad, y3 + pad + 30);
    ctx.fillText(`EFFECT: GLOW / GRAIN`, pad, y4 + pad + 30);
  };

  // --- [메인 실행 함수] ---
  const generateImage = (imagePaths) => {
    const canvas = canvasRef.current;
    const ctx = canvas.getContext("2d");
    const width = canvas.width;
    const height = canvas.height;

    ctx.fillStyle = "#111";
    ctx.fillRect(0, 0, width, height);

    const loadImage = (src) =>
      new Promise((resolve) => {
        const img = new Image();
        img.crossOrigin = "Anonymous";
        img.onload = () => resolve(img);
        img.src = src;
      });

    Promise.all(imagePaths.map(loadImage)).then((images) => {
      // 1. 이미지 합성 (Source Canvas 생성)
      const compositeCanvas = document.createElement('canvas');
      compositeCanvas.width = width;
      compositeCanvas.height = height;
      const compositeCtx = compositeCanvas.getContext('2d');

      compositeCtx.fillStyle = "#000";
      compositeCtx.fillRect(0, 0, width, height);
      compositeCtx.globalCompositeOperation = 'screen'; 

      images.forEach(img => {
          compositeCtx.drawImage(img, 0, 0, width, height);
      });

      // 2. 프로세스 레이어 그리기
      drawProcessLayers(ctx, width, height, compositeCanvas);

      // 3. 후처리
      generateGrain(ctx, width, height);
      applyScanlines(ctx, width, height);
      applySaturation(ctx, width, height);
      applyGlitchEffect(ctx, width, height);
    });
  };

  const handleDownload = () => {
    const canvas = canvasRef.current;
    const link = document.createElement("a");
    link.download = "process_archive.png";
    link.href = canvas.toDataURL("image/png");
    link.click();
  };

  const handleRegenerate = () => {
    setIsFading(true);
    setTimeout(() => {
      generateImage(imagePaths);
      setIsFading(false);
    }, 300);
  };

  const handleBack = () => {
    localStorage.removeItem("generatedImage");
    localStorage.removeItem("selectedImages");
    setImagePaths([]);
    setIsFading(false);
    navigate("/");
  };

  return (
    <div className="ge-container">
      <div className="ge-title-container">
        <img src="/images/logo.gif" alt="Graphic Archive" style={{ height: '60px', width: 'auto', objectFit: 'contain' }} />
      </div>

      <div className="ge-main">
        <div className="ge-box1">
          <div className="ge-effects-panel">
            <h3 style={{ margin: "0 0 15px 0", fontSize: "16px", fontWeight: "500" }}>Controls</h3>
            <div style={{ display: "flex", flexDirection: "column", gap: "15px" }}>
              <div>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                  <label style={{ fontSize: "14px" }}>Grain</label>
                  <span style={{ fontSize: "12px", opacity: 0.7 }}>{effects.grain.intensity}%</span>
                </div>
                <input type="range" min="0" max="100" step="10" value={effects.grain.intensity} onChange={(e) => setEffects(p => ({...p, grain: {...p.grain, intensity: Number(e.target.value)}}))} style={{ width: "100%" }} />
              </div>
              <div>
                <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "5px" }}>
                  <label style={{ fontSize: "14px" }}>Glitch</label>
                  <span style={{ fontSize: "12px", opacity: 0.7 }}>{effects.glitch.shiftAmount}%</span>
                </div>
                <input type="range" min="0" max="100" step="10" value={effects.glitch.shiftAmount} onChange={(e) => setEffects(p => ({...p, glitch: {...p.glitch, shiftAmount: Number(e.target.value)}}))} style={{ width: "100%" }} />
              </div>
            </div>
          </div>

          <div className="ge-button-container">
            <button onClick={handleBack} className="ge-button ge-button-back">Back</button>
            <button onClick={handleArchive} className="ge-button ge-button-archive">Archive</button>
            <button onClick={handleRegenerate} className="ge-button ge-button-regenerate">Regenerate</button>
            <button onClick={handleDownload} className="ge-button ge-button-download">Download</button>
          </div>
        </div>

        <div className="ge-canvas-container">
          <canvas ref={canvasRef} width={1080} height={1080} className="ge-canvas" style={{ opacity: isFading ? 0.2 : 1 }} />
        </div>
      </div>
    </div>
  );
}

export default Generate;
